#include <vector>
#include <stack>
#include <cassert>

using namespace std;

// LeetCode 42. Trapping Rain Water
// 给定 n 个非负整数表示每个宽度为 1 的柱子的高度图，
// 计算按此排列的柱子下雨之后能接多少雨水。
//
// 示例:
//   height = [0,1,0,2,1,0,1,3,2,1,2,1]  ->  6

class Solution {
public:
    // 方法一：双指针（最优解）
    // 时间复杂度 O(n)，空间复杂度 O(1)
    int trap(vector<int>& height) {
        if (height.size() < 3) return 0;

        int left = 0, right = (int)height.size() - 1;
        int leftMax = 0, rightMax = 0;
        int water = 0;

        while (left < right) {
            if (height[left] < height[right]) {
                // 左边较矮，决定水位的是左侧最高柱
                if (height[left] >= leftMax) {
                    leftMax = height[left];          // 更新左边界最高点
                } else {
                    water += leftMax - height[left]; // 当前位置能接的水
                }
                ++left;
            } else {
                // 右边较矮，决定水位的是右侧最高柱
                if (height[right] >= rightMax) {
                    rightMax = height[right];
                } else {
                    water += rightMax - height[right];
                }
                --right;
            }
        }
        return water;
    }

    // 方法二：动态规划（预先计算左右最大值）
    // 时间复杂度 O(n)，空间复杂度 O(n)
    int trapDP(vector<int>& height) {
        int n = (int)height.size();
        if (n < 3) return 0;

        vector<int> leftMax(n), rightMax(n);
        leftMax[0] = height[0];
        for (int i = 1; i < n; ++i)
            leftMax[i] = max(leftMax[i - 1], height[i]);

        rightMax[n - 1] = height[n - 1];
        for (int i = n - 2; i >= 0; --i)
            rightMax[i] = max(rightMax[i + 1], height[i]);

        int water = 0;
        for (int i = 0; i < n; ++i)
            water += min(leftMax[i], rightMax[i]) - height[i];
        return water;
    }

    // 方法三：单调递减栈
    // 时间复杂度 O(n)，空间复杂度 O(n)
    int trapStack(vector<int>& height) {
        int n = (int)height.size();
        if (n < 3) return 0;

        stack<int> st; // 存下标，对应高度单调不增
        int water = 0;

        for (int i = 0; i < n; ++i) {
            while (!st.empty() && height[i] > height[st.top()]) {
                int bottom = st.top(); // 凹槽底部
                st.pop();
                if (st.empty()) break; // 左边没有墙，存不住水

                int left = st.top();
                int width = i - left - 1;
                int h = min(height[left], height[i]) - height[bottom];
                water += width * h;
            }
            st.push(i);
        }
        return water;
    }
};

// ---------- 测试 ----------
static void runTests() {
    Solution sol;

    // 官方示例
    {
        vector<int> h = {0,1,0,2,1,0,1,3,2,1,2,1};
        assert(sol.trap(h) == 6);
        assert(sol.trapDP(h) == 6);
        assert(sol.trapStack(h) == 6);
    }
    // 示例 2
    {
        vector<int> h = {4,2,0,3,2,5};
        assert(sol.trap(h) == 9);
        assert(sol.trapDP(h) == 9);
        assert(sol.trapStack(h) == 9);
    }
    // 空数组 / 单柱 / 双柱
    {
        vector<int> h;
        assert(sol.trap(h) == 0);
        assert(sol.trapDP(h) == 0);
        assert(sol.trapStack(h) == 0);

        vector<int> h1 = {5};
        assert(sol.trap(h1) == 0);
        assert(sol.trapDP(h1) == 0);
        assert(sol.trapStack(h1) == 0);

        vector<int> h2 = {2, 2};
        assert(sol.trap(h2) == 0);
        assert(sol.trapDP(h2) == 0);
        assert(sol.trapStack(h2) == 0);
    }
    // 递增 / 递减，存不住水
    {
        vector<int> inc = {1,2,3,4,5};
        assert(sol.trap(inc) == 0);
        assert(sol.trapDP(inc) == 0);
        assert(sol.trapStack(inc) == 0);

        vector<int> dec = {5,4,3,2,1};
        assert(sol.trap(dec) == 0);
        assert(sol.trapDP(dec) == 0);
        assert(sol.trapStack(dec) == 0);
    }
    // 凹槽形状
    {
        vector<int> h = {3,0,0,0,3};
        assert(sol.trap(h) == 9);
        assert(sol.trapDP(h) == 9);
        assert(sol.trapStack(h) == 9);
    }

    cout << "全部测试通过！" << endl;
}

int main(int argc, char* argv[]) {
    // 支持 --test 自测模式
    if (argc > 1 && string(argv[1]) == "--test") {
        runTests();
        return 0;
    }

    // 交互模式：从命令行读取高度数组
    Solution sol;
    cout << "请输入柱子高度（以空格分隔，回车结束）：" << endl;
    vector<int> height;
    int x;
    while (cin >> x) height.push_back(x);

    if (height.empty()) {
        cout << "未输入数据，接水量为 0。" << endl;
        return 0;
    }

    cout << "接水量（双指针）: " << sol.trap(height) << endl;
    cout << "接水量（动态规划）: " << sol.trapDP(height) << endl;
    cout << "接水量（单调栈）: " << sol.trapStack(height) << endl;
    return 0;
}
"}

